 const sheet=$('#ai-chat-dialog'),sheetToggle=$('#ai-rules-btn');let sheetOpen=false,sheetHideTimer=0;
 function syncPhoneSheet(){const phone=MobileUI.isPhone();document.body.classList.toggle('phone-ai-open',phone&&sheetOpen);const workspace=document.querySelector('.workspace');workspace.inert=false;workspace.removeAttribute('inert');if(phone&&sheetOpen)workspace.setAttribute('aria-hidden','true');else workspace.removeAttribute('aria-hidden');$('#ai-chat-close').setAttribute('aria-label',phone?'返回规则':'收起 AI 问答');if(phone&&sheetOpen)MobileUI.enter('rules-ai',()=>{closeSheet(false);return true;});}
